#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms: 10,
            max_delay_ms: 25,
        }
    }

    #[test]
    fn retries_transient_errors_and_succeeds() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();

        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(RetryError::Transient("temporary outage".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_errors_are_returned_without_retrying() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();
        let error = RetryError::Permanent("invalid job".into());

        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(error.clone())
        });

        assert_eq!(result, Err(error));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut calls = 0;
        let mut sleeper = FakeSleeper::default();

        let result = run_job(&config(3), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still unavailable".into()))
        });

        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
        assert_eq!(result, Err(RetryError::Transient("still unavailable".into())));
    }

    #[test]
    fn zero_attempt_budget_still_runs_once() {
        let mut calls = 0;
