use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_with_a_bounded_delay() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 10,
        max_delay_ms: 25,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 5 {
            Err(RetryError::Transient("temporary failure".to_owned()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}

#[test]
fn public_api_does_not_retry_permanent_failures() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 10,
        max_delay_ms: 25,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid input".to_owned()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid input".to_owned())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

